window.ScripturaLexicons.BDAG_PART_0041 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aperchomai-bdag\" data-source=\"BDAG\" data-search=\"ἀπέρχομαι apérchomai afastar-se partir ir adiante passar sair evangelhos Marcos Lucas João Atos Judas discípulos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέρχομαι</td><td>Verbo</td><td>ir embora; partir; passar; espalhar-se; seguir</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apestalen-bdag\" data-source=\"BDAG\" data-search=\"ἀπεστάλην, ἀπέσταλκα, ἀπέστειλα apestálēn remissão apostello enviar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπεστάλην, ἀπέσταλκα, ἀπέστειλα</td><td>Formas verbais (remissão)</td><td>formas de ἀποστέλλω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apesten-bdag\" data-source=\"BDAG\" data-search=\"ἀπέστην, ἀπέστησα apéstēn remissão aphistemi afastar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέστην, ἀπέστησα</td><td>Formas verbais (remissão)</td><td>formas de ἀφίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apestraphen-bdag\" data-source=\"BDAG\" data-search=\"ἀπεστράφην apestráphēn remissão apostrepho desviar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπεστράφην</td><td>Forma verbal (remissão)</td><td>forma de ἀποστρέφω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apecho-bdag\" data-source=\"BDAG\" data-search=\"ἀπέχω apéchō pagamento quitação recebido suficiente Marcos 14 41 abster idolotitos sangue sufocado fornicação Atos 15 29 distância BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπέχω</td><td>Verbo</td><td>receber integralmente; bastar; distar; abster-se</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apegagon-bdag\" data-source=\"BDAG\" data-search=\"ἀπήγαγον apḗgagon remissão apago conduzir levar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπήγαγον</td><td>Forma verbal (remissão)</td><td>forma de ἀπάγω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apegxamen-bdag\" data-source=\"BDAG\" data-search=\"ἀπηγξάμην apēnxámēn remissão apagcho enforcar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπηγξάμην</td><td>Forma verbal (remissão)</td><td>forma de ἀπάγχω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apiesan-bdag\" data-source=\"BDAG\" data-search=\"ἀπῄεσαν apḗesan remissão apeimi II ir embora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπῄεσαν</td><td>Forma verbal (remissão)</td><td>forma de ἄπειμι II</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apelasa-bdag\" data-source=\"BDAG\" data-search=\"ἀπήλασα apḗlasa remissão apelauno expulsar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπήλασα</td><td>Forma verbal (remissão)</td><td>forma de ἀπελαύνω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apeltha-bdag\" data-source=\"BDAG\" data-search=\"ἀπῆλθα, ἀπῆλθον apē̂ltha remissão aperchomai partir ir embora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπῆλθα, ἀπῆλθον</td><td>Formas verbais (remissão)</td><td>formas de ἀπέρχομαι</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apellachthai-bdag\" data-source=\"BDAG\" data-search=\"ἀπηλλάχθαι apēlláchthai remissão apallasso libertar separar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπηλλάχθαι</td><td>Forma verbal (remissão)</td><td>forma de ἀπαλλάσσω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aperth-bdag\" data-source=\"BDAG\" data-search=\"ἀπήρθη apḗrthē remissão apairo levantar tirar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπήρθη</td><td>Forma verbal (remissão)</td><td>forma de ἀπαίρω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apido-bdag\" data-source=\"BDAG\" data-search=\"ἀπίδω apídō remissão aphorao ver olhar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπίδω</td><td>Forma verbal (remissão)</td><td>forma de ἀφοράω</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apisteo-bdag\" data-source=\"BDAG\" data-search=\"ἀπιστέω apistéō apisteo não crer; recusar-se a crer; não depositar fé; ser infiel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπιστέω</td><td>Verbo</td><td>não crer; recusar-se a crer; não depositar fé; ser infiel</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apistia-bdag\" data-source=\"BDAG\" data-search=\"ἀπιστία apistía apistia incredulidade; falta de fé; infidelidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπιστία</td><td>Substantivo feminino</td><td>incredulidade; falta de fé; infidelidade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-apistos-bdag\" data-source=\"BDAG\" data-search=\"ἄπιστος ápistos apistos incrível; inacreditável; incrédulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄπιστος</td><td>Adjetivo</td><td>incrível; inacreditável; incrédulo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aplanes-bdag\" data-source=\"BDAG\" data-search=\"ἀπλανής aplanḗs aplanes infalível; sem desvios; correto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀπλανής</td><td>Adjetivo</td><td>infalível; sem desvios; correto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haplotes-bdag\" data-source=\"BDAG\" data-search=\"ἁπλότης haplótēs haplotes simplicidade; sinceridade; retidão; franqueza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁπλότης</td><td>Substantivo feminino</td><td>simplicidade; sinceridade; retidão; franqueza</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haplous-bdag\" data-source=\"BDAG\" data-search=\"ἁπλοῦς haploûs haplous simples; sincero; singelo; sem dolo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁπλοῦς</td><td>Adjetivo</td><td>simples; sincero; singelo; sem dolo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haploo-bdag\" data-source=\"BDAG\" data-search=\"ἁπλόω haplóō haploo tornar simples; estender; desdobrar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁπλόω</td><td>Verbo</td><td>tornar simples; estender; desdobrar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aplutos-bdag\" data-source=\"BDAG\" data-search=\"ἄπλυτος áplutos aplutos não lavado; sujo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄπλυτος</td><td>Adjetivo</td><td>não lavado; sujo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-haplos-bdag\" data-source=\"BDAG\" data-search=\"ἁπλῶς haplō̂s haplos simplesmente; sinceramente; francamente; em suma BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁπλῶς</td><td>Advérbio</td><td>simplesmente; sinceramente; francamente; em suma</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-aperchomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέρχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apérchomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek\">ἀπελεύσομαι</span>; aoristo <span class=\"greek\">ἀπῆλθον</span>; terceira pessoa do plural <span class=\"greek\">ἀπῆλθαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.46\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 11.46</a> P66 e GJs 9.1 (veja B-D-F §81, 3); <span class=\"greek\">ἀπήλθασιν</span>, GJs 10.1; 24.1; terminação <span class=\"greek\">-οσαν</span>, Jdth 13.4 (compare <span class=\"greek\">-ωσαν</span>, GJs 23.2); perfeito <span class=\"greek\">ἀπελήλυθα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.24</a>; particípio <span class=\"greek\">ἀπεληλυθώς</span>, Hs 9.5.4; mais-que-perfeito <span class=\"greek\">ἀπεληλύθειν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.8</a>; veja B-D-F §101, <span class=\"greek\">ἔρχεσθαι</span>; semelhantemente W-S §15. Desde Homero.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Mover-se para longe de um ponto de referência</strong>, de pessoas ou coisas.</p>\n<p class=\"entry-text\"><strong>a.</strong> <strong>Ir embora, partir</strong>, sem indicação do destino (1Mc 9.36; 2Mc 14.34; 1Esd 4.11): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">13.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.4\" target=\"_blank\" rel=\"noopener noreferrer\">16.4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.29\" target=\"_blank\" rel=\"noopener noreferrer\">28.29</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.24</a>. O particípio <span class=\"greek\">ἀπελθών</span> associado ao indicativo, subjuntivo ou imperativo de outro verbo equivale a <strong>ir embora e [fazer algo]</strong>; compare Epicteto, índice de Sch.; Gn 21.14, 16 e outras passagens; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.28</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">13.46</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.30\" target=\"_blank\" rel=\"noopener noreferrer\">18.30</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.18\" target=\"_blank\" rel=\"noopener noreferrer\">25.18</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.25\" target=\"_blank\" rel=\"noopener noreferrer\">25.25</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.27</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.37\" target=\"_blank\" rel=\"noopener noreferrer\">6.37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.14</a>.</p>\n<p class=\"entry-text\">Com indicação da pessoa ou do lugar de origem, <span class=\"greek\">ἀπό τινος</span> (Tucídides 8.92.2; UPZ 61, 6s. [161 a.C.], <span class=\"greek\">ἀφ’ ὑμῶν ἀπελήλυθα</span>; Epicteto 3.15.11; 3Rs 21.36; Tb 14.8): <span class=\"greek\">ἀπὸ τῶν ὁρίων αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.17</a>; <span class=\"greek\">ἀπ’ αὐτῆς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.38</a>; <span class=\"greek\">ἀπ’ αὐτῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">8.37</a>; <span class=\"greek\">ἔξω τοῦ συνεδρίου</span>, <strong>para fora do Sinédrio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 4.15</a>, compare Jdth 6.12; num barco, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.22</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> <strong>Ir</strong>, em oposição a <span class=\"greek\">ἐξέρχεται</span>, GrBar 9.2; compare <span class=\"greek\">πόθεν ἔρχει καὶ ποῦ ἀπέρχει</span>, TestAbr B 2, p. 106, 4ss. [Stone p. 60], cód. C. Com indicação do destino por <span class=\"greek\">εἰς</span>, <strong>ir para, dirigir-se a</strong>: Simplício sobre Epicteto p. 134, 51, <span class=\"greek\">ἀπέρχεσθαι εἰς τὸ ἱερόν</span>; a propósito de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.24</a>, veja 3. <span class=\"greek\">εἰς ἔρημον τόπον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.35</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.36\" target=\"_blank\" rel=\"noopener noreferrer\">6.36</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">6.46</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">7.24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">14.15</a>. Com <span class=\"greek\">ἐπὶ τὸν τόπον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.33</a> v.l.; <span class=\"greek\">εἰς τὸν οἶκον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9.7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 1.23</a>; Hs 9.11.2; <span class=\"greek\">εἰς τὴν Γαλιλαίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28.10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">4.43</a> v.l.; <span class=\"greek\">εἰς Σπανίαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.28</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1.16</a> v.l., por <span class=\"greek\">διελθεῖν</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.17</a>. Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.66\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.66</a>, veja 5.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">ἐπί τι</span> (Josefo, <em>Vi.</em> 151): <span class=\"greek\">ἐπὶ τὸ μνημεῖον</span>, <strong>ao sepulcro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.24</a>; compare 3Rs 19.19 v.l. e Epicteto 4.7.30. Com <span class=\"greek\">ἐν</span>: Hs 1.6; compare Diodoro Sículo 23.18.5, <span class=\"greek\">ἀπῆλθεν ἐν Μεσσήνῃ</span>; <em>Pel.-Leg.</em> p. 7, 3; Epicteto 2.20.33, <span class=\"greek\">ἀπελθεῖν ἐν βαλανείῳ</span>. Com dativo simples (compare PFay 113, 12 [100 d.C.], <span class=\"greek\">τῇ πόλει πέμψας</span>): <span class=\"greek\">ποίῳ τόπῳ ἀπῆλθεν</span>, Hv 4.3.7.</p>\n<p class=\"entry-text\">De um espírito possessivo ou demônio (Trásilo, século I d.C.: 622 Fgm. 1, 2, 3 Jac. [em Ps.-Plutarco, <em>Fluv.</em> 16.2]; PGM 13, 244): <span class=\"greek\">ἀπέρχεσθαι εἰς τοὺς χοίρους</span>, <strong>ir para os porcos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.32</a>.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">πρός τινα</span>, <strong>ir até alguém</strong>, compare PFay 123, 19 [100 d.C.]; BGU 884 II, 13s.; 1Rs 25.5; 1Mc 7.20: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.25</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 10.9</a>. <strong>Talvez</strong> também <span class=\"greek\">πρὸς αὐτούς</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.10</a> (v.l. <span class=\"greek\">ἑαυτούς</span>; veja <span class=\"greek\">ἑαυτοῦ</span>), uma expressão coloquial que poderia significar <strong>reuniram-se novamente a seu grupo</strong>, isto é, aos discípulos, como na <em>Twentieth Century NT</em>. A versão segundo a qual “voltaram para suas casas”, atribuída à NSRV e a outras traduções, <strong>parece improvável</strong>, compare C. Barrett, comentário à passagem, à luz da descrição dos discípulos reunidos no v. 19. A redação aparentemente pouco explícita, que pressupõe conhecimento prévio da narrativa, é característica de numerosas construções coloquiais do Evangelho de João.</p>\n<p class=\"entry-text\">A variante <span class=\"greek\">(πρὸς) ἑαυτούς</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.10</a> admite o sentido <strong>ir para casa</strong>, como <span class=\"greek\">πρὸς ἑαυτόν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.12</a> (v.l. <span class=\"greek\">αὐτόν</span>). Sobre essas passagens, veja F. Neirynck, <em>ETL</em> 54 (1978), 104–118; R. Borger, <em>GGA</em> 130s.; idem, <em>TU</em> 52 (1987), 34; para a leitura <span class=\"greek\">αὑτούς</span> de N25 em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.10</a>, compare Josefo, <em>Ant.</em> 8.124, mas veja também Metzger 254, 615s. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16.7</a>, <span class=\"greek\">πρὸς τὸν πατέρα</span> deve ser suprido pelo contexto; compare PPetr II, 13 [19], 7 [252 a.C.], <span class=\"greek\">εἰς θεοὺς ἀπελθεῖν</span>.</p>\n<p class=\"entry-text\">Também de deslocamento em barco: <span class=\"greek\">εἰς τὸ πέραν</span>, <strong>atravessar para o outro lado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8.18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8.13</a>; <span class=\"greek\">εἰς ἔρημον τόπον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.32</a>. Sem destino expresso, quando o contexto fornece o objetivo (compare POxf 16, 16, “para uma festa”), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17.23</a>. Com infinitivo de finalidade (veja <span class=\"greek\">ἔρχομαι</span> 1aε), GJs 9.3. De pedras, com a conotação de adequação para um propósito: <span class=\"greek\">εἰς τὴν οἰκοδομήν</span>, <strong>ir para a construção</strong>, Hs 9.5.3–4; 9.14.2. Em uso absoluto, <span class=\"greek\">εἰς τὰ ὀπίσω</span>, <strong>recuar um pouco</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.6</a>. Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.66\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.66</a>, veja 5.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Deixar de existir como condição ou estado; desaparecer, cessar</strong>, de doenças e fenômenos semelhantes; compare Cebes 14.3, <span class=\"greek\">οὐ μὴ ἀπέλθῃ ἀπ’ αὐτῶν ἡ κακία</span>; Êx 8.25. <span class=\"greek\">ἀπῆλθεν ἀπ’ αὐτοῦ ἡ λέπρα</span>, <strong>a lepra desapareceu dele</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.13</a>. <span class=\"greek\">ἡ ὀπώρα ἀπῆλθεν ἀπὸ σοῦ</span>, <strong>teus frutos desapareceram</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18.14</a>. Em geral, <strong>passar, desaparecer</strong>, compare Ct 2.11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 9.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">11.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">21.1</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.4\" target=\"_blank\" rel=\"noopener noreferrer\">21.4</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Sair de uma fonte e difundir-se; espalhar-se</strong>, de uma notícia ou mensagem: <span class=\"greek\">εἰς ὅλην τὴν Συρίαν</span>, <strong>por toda a Síria</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.24</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Esforçar-se por alcançar alguma coisa, ir atrás de</strong>; a respeito dos habitantes de Sodoma: <span class=\"greek\">ἀπέρχεσθαι ὀπίσω σαρκὸς ἑτέρας</span>, <strong>ir após uma carne diferente da sua própria</strong>, isto é, seres humanos buscando relações sexuais com figuras transcendentes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 7</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> <strong>Abandonar a associação com alguém, afastar-se, deixar</strong>: <span class=\"greek\">ἀπῆλθον εἰς τὰ ὀπίσω</span>, <strong>voltaram atrás, retiraram-se</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.66\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.66</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">6.</span> Expressão idiomática <span class=\"greek\">ἀπέρχεσθαι ὀπίσω τινός</span> (Jó 21.33): <strong>deixar um lugar para tornar-se seguidor de alguém, ir após, seguir alguém</strong>. Dos discípulos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1.20</a>; do mundo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12.19</a>. — DELG s.v. <span class=\"greek\">ἐλεύσομαι</span>. M-M. TW.</p>\n</section></article><article id=\"entry-apestalen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπεστάλην, ἀπέσταλκα, ἀπέστειλα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apestálēn⟧</span><span class=\"separator\">·</span><span>formas verbais (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Formas verbais; veja <span class=\"greek\">ἀποστέλλω</span>.</p>\n</section></article><article id=\"entry-apesten-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέστην, ἀπέστησα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apéstēn⟧</span><span class=\"separator\">·</span><span>formas verbais (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Formas verbais; veja <span class=\"greek\">ἀφίστημι</span>.</p>\n</section></article><article id=\"entry-apestraphen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπεστράφην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apestráphēn⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἀποστρέφω</span>.</p>\n</section></article><article id=\"entry-apecho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπέχω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apéchō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Segundo aoristo <span class=\"greek\">ἀπέσχον</span>; perfeito na terceira pessoa do singular <span class=\"greek\">ἀπέσχηκεν</span>, LXX; futuro médio <span class=\"greek\">ἀφέξομαι</span>; aoristo <span class=\"greek\">ἀπεσχόμην</span>, LXX; infinitivo <span class=\"greek\">ἀποσχέσθαι</span>; perfeito na primeira pessoa do plural <span class=\"greek\">ἀπεσχήμεθα</span>, 1Rs 21.6 e outras passagens. Desde Homero; inscrições, papiros, LXX, Enoque, TestAbr A, Test12Patr, ParJer 7.37, Fílon, Josefo, Justino e Atanásio.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> <strong>Receber integralmente aquilo a que se tem direito; receber o pagamento completo</strong>, no ativo. Termo técnico comercial para <strong>dar quitação de uma soma paga integralmente</strong>, utilizado literal e figuradamente. Calímaco, <em>Epigr.</em> 50, 4 [Pf.], de uma ama que recebe agradecimento na forma de memorial; SIG² 845, 7 [200 a.C.], <span class=\"greek\">τὰν τιμὰν ἀπέχει</span>; Marco Aurélio 9.42, <span class=\"greek\">ἀπέχει τὸ ἴδιον</span>. Frequente em papiros e óstracos; veja Dssm., <em>NB</em> 56 [BS 229]; <em>LO</em> 88ss. [LAE 110s.]; Erman, <em>APF</em> 1 (1901), 77ss.; Mayser 487; O. Wilck I 86; Nägeli 54s.; Anz 318s.; Gn 43.23; Nm 32.19; Josefo, <em>Bell.</em> 1.596, <span class=\"greek\">ἀπέχειν τῆς ἀσεβείας τὸ ἐπιτίμιον</span>.</p>\n<p class=\"entry-text\"><span class=\"greek\">τὸν μισθόν</span>, <strong>o salário, a recompensa</strong>, compare Plutarco, <em>Sol.</em> 90 [22, 4], <em>Mor.</em> 334a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.2</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">6.5</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">6.16</a>. <span class=\"greek\">τὴν παράκλησιν</span>, <strong>o consolo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.24</a>. <span class=\"greek\">πάντα</span>, <strong>tudo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4.18</a>; <span class=\"greek\">τὸ τέλειον τῆς γνώσεως</span>, <strong>o conhecimento perfeito</strong>, B 13.7; <span class=\"greek\">ἀπέχειν τὴν ἀποκάλυψιν</span>, <strong>ter recebido a revelação</strong>, Hv 3.13.4.</p>\n<p class=\"entry-text\">Semelhantemente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Fm 15</a>, <span class=\"greek\">ἵνα αἰώνιον αὐτὸν ἀπέχῃς</span>, <strong>para que o recebas de volta para sempre</strong>, em contraste com <span class=\"greek\">χωρίζεσθαι πρὸς ὥραν</span>, <strong>separar-se por uma hora</strong>. Alguns aplicam aqui o difícil <span class=\"greek\">ἀπέχει</span> impessoal de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.41</a>, no sentido <strong>a conta está encerrada</strong>; veja J. de Zwaan, <em>Exp.</em>, 6ª série, 12 (1905), 459–472, que considera o informante do v. 42 o sujeito: <strong>ele recebeu o dinheiro</strong>. Veja 2 e 3.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Satisfazer a necessidade do momento, ser suficiente, bastar</strong>. Para <span class=\"greek\">ἀπέχει</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.41</a>, a Vulgata apresenta <em>sufficit</em>, <strong>basta, é suficiente</strong>, leitura amparada por testemunhos relativamente tardios: <em>Anacreontea Carmina</em> 16.33 [Preis., West, Campbell]; PStras 4, 19, nota [550 d.C.]; PLond 1343, 38 [709 d.C.], leitura duvidosa. Muitas traduções a seguem, inclusive REV e NRSV, <strong>Basta!</strong>. O fato de a expressão não ser encontrada com essa acepção em outra literatura não surpreende, pois se trata de coloquialismo que aflora em enunciados dramáticos, como nos <em>Anacreontea</em>. Neste caso, como em <span class=\"greek\">ἀπελπίζω</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.35</a>, o contexto é determinante para o significado.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> A expressão relativamente frequente <span class=\"greek\">οὐδὲν ἀπέχει</span>, <strong>nada impede</strong>, compare Platão, <em>Cra.</em> 23 p. 407b; Plutarco, <em>Mor.</em> 433a; 680e, sugere para <span class=\"greek\">ἀπέχει</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14.41</a> a interpretação <strong>isso é um impedimento</strong>, referindo-se à extrema sonolência dos discípulos no momento decisivo. <strong>Mas veja 1 e 2</strong>.</p>\n<p class=\"entry-text\">O manuscrito D apresenta <span class=\"greek\">ἀπέχει τὸ τέλος</span>, <strong>este é o fim</strong>; veja B-D-F §129; J. Wackernagel, <em>Syntax</em> I² (1926), 119; compare Kaibel 259, 4 [século II d.C.], <span class=\"greek\">ἀπέσχε τέλος</span>, <strong>morreu</strong>. M. Black, <em>An Aramaic Approach</em> (1946), 16s., sugere um pano de fundo aramaico. G. Boobyer, <em>NTS</em> 2 (1955), 44–48, propõe <strong>ele (Judas) está tomando posse de mim</strong>. Essas interpretações são registradas como alternativas, sem serem equiparadas a certeza.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Estar a alguma distância de um ponto, estar distante</strong>, intransitivo; Heródoto e outros; PStras 57, 6; PLille 1, 5; 2, 2; Josefo, <em>Ant.</em> 5.161; Justino, <em>A I</em> 34.2; Atanásio 32.1. <span class=\"greek\">αὐτοῦ μακρὰν ἀπέχοντος</span>, <strong>quando ele ainda estava longe</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 15.20</a>; compare Diodoro Sículo 12.33.4, <span class=\"greek\">μακρὰν ἀπέχειν</span>; Gn 44.4; Jl 4.8; En 32.2.</p>\n<p class=\"entry-text\">Com indicação do lugar de referência (1Mc 8.4; 2Mc 11.5), <span class=\"greek\">οὐ μακρὰν ἀπέχων ἀπὸ τῆς οἰκίας</span>, <strong>não estando longe da casa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7.6</a>; compare MPol 5.1. De barco distante da terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14.24</a>, como Michel 466, 9, <span class=\"greek\">ἀπέχον ἀπὸ τῆς γῆς</span>. Com indicação precisa da distância (desde Tucídides 2.5.2): <span class=\"greek\">κώμη ἀπέχουσα σταδίους ἑξήκοντα ἀπὸ Ἰερουσαλήμ</span>, <strong>povoado situado a sessenta estádios de Jerusalém</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.13</a>; Demétrio de Calátis [200 a.C.], 85 Fgm. 2 Jac., <span class=\"greek\">ἀπεχούσης τῆς νήσου ἀπὸ τῆς ἠπείρου σταδίους υ’</span>; compare o poeta cômico Eufron [século III a.C.], 11, 3 Kock; Apiano, <em>Ital.</em> 5 §1; 2Mc 12.29; Josefo, <em>Bell.</em> 2.516; Justino, <em>A I</em> 34.2.</p>\n<p class=\"entry-text\">Figuradamente, <span class=\"greek\">πόρρω ἀπέχειν ἀπό τινος</span>, <strong>estar longe de alguém</strong>, equivalente ao hebraico <span class=\"greek\">רָחַק מִן</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.6</a>, ambos Is 29.13; também PEg² 57s.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">5.</span> <strong>Evitar contato com algo ou deixar de fazer ou utilizar algo; afastar-se, abster-se</strong>, no médio com genitivo de coisa. Desde Homero; SIG 768, 16 [31 a.C.]; PHerm 52, 21; StudPal V, 52, 21; 1Esd 6.26; Wsd 2.16; <span class=\"greek\">σου</span>, PsSol 8.32; <span class=\"greek\">τούτου</span>, TestAbr A 2 p. 79, 8 [Stone p. 6]; Josefo, <em>Bell.</em> 2.581, <em>Ant.</em> 11.101; Justino, <em>A II</em> 7.7 e outros; Atanásio.</p>\n<p class=\"entry-text\"><span class=\"greek\">εἰδωλοθύτων καὶ αἵματος καὶ πνικτῶν καὶ πορνείας</span>, <strong>abster-se de coisas sacrificadas a ídolos, de sangue, de animais sufocados e de relações sexuais ilícitas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.29</a>; veja Lv 18.6–30 e compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.20</a> (veja <span class=\"greek\">αἷμα</span> 1b). <span class=\"greek\">πάσης ἀδικίας</span>, <strong>de toda injustiça</strong>, Pol 2.2; compare Hipérides, Fgm. 210, <span class=\"greek\">τῶν ἀδικημάτων</span>; SIG 1268 I, 18 [século III a.C.], <span class=\"greek\">κακίας ἀπέχου</span>; Atanásio 1, 2, <span class=\"greek\">τοῦ ἀδικεῖν</span>; Pol 6.1, 3; Hv 1.2.4; 2.2.3; 3.8.4; Hm 3.5; Dg 4.6. <span class=\"greek\">τῶν κακῶν βοτανῶν</span>, <strong>das ervas nocivas</strong>, IPhld 3.1; compare ITr 6.1. <span class=\"greek\">βρωμάτων</span>, <strong>de alimentos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 4.3</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">εὐχαριστίας καὶ προσευχῆς</span>, <strong>afastar-se da Ceia do Senhor e da oração</strong>, ISm 7.1; a reação àqueles que se afastam da refeição do Senhor é interromper as relações sociais com eles, v. 2; compare escólio a Platão, <em>Euthyphr.</em> 2 A, <span class=\"greek\">ἀπέχεσθαι μυστηρίων</span>, <strong>manter-se afastado dos mistérios</strong>. <span class=\"greek\">τῶν σαρκικῶν ἐπιθυμιῶν</span>, <strong>dos desejos carnais</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.11</a>; D 1.4. <span class=\"greek\">τῆς γλώσσης</span>, <strong>controlar a língua</strong>, Hv 2.2.3. <span class=\"greek\">λατρείας</span>, <strong>do culto</strong>, Dg 3.2.</p>\n<p class=\"entry-text\">Com <span class=\"greek\">ἀπό τινος</span> (frequente na LXX; En 104.6; TestAbr A 4 p. 81, 4 [Stone p. 10]; com <span class=\"greek\">ἐκ</span>, ParJer 7.37 [7.32 Harris]): <span class=\"greek\">ἀπὸ τῆς πορνείας</span>, <strong>da imoralidade sexual</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 4.3</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 15.20</a>, v.l. <span class=\"greek\">ἀπό</span>; <span class=\"greek\">ἀπὸ παντὸς εἴδους πονηροῦ</span>, <strong>de toda forma de mal</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 5.22</a>; <span class=\"greek\">ἀπὸ παντὸς κακοῦ</span>, <strong>de todo mal</strong>, 1Cl 17.3 (Jó 1.1, 8; 2.3). <span class=\"greek\">ἀπέχεσθε ἀπὸ τῶν ἀνθρώπων</span>, <strong>não toqueis nesses homens, afastai-vos deles</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">At 5.39</a>, códice D. Outras ocorrências: Pol 5.3; Hm 2.3; 4.1.3 e 9; 5.1.7; 5.2.8; 7.3; 9.12; 11.4, 8, 21; 12.1.3; 12.2.2; Hs 4.5. — DELG s.v. <span class=\"greek\">ἔχω</span>. M-M. TW. Spicq.</p>\n</section></article><article id=\"entry-apegagon-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπήγαγον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apḗgagon⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἀπάγω</span>.</p>\n</section></article><article id=\"entry-apegxamen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπηγξάμην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apēnxámēn⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἀπάγχω</span>.</p>\n</section></article><article id=\"entry-apiesan-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπῄεσαν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apḗesan⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἄπειμι II</span>.</p>\n</section></article><article id=\"entry-apelasa-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπήλασα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apḗlasa⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἀπελαύνω</span>.</p>\n</section></article><article id=\"entry-apeltha-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπῆλθα, ἀπῆλθον</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apē̂ltha⟧</span><span class=\"separator\">·</span><span>formas verbais (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Formas verbais; veja <span class=\"greek\">ἀπέρχομαι</span>.</p>\n</section></article><article id=\"entry-apellachthai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπηλλάχθαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apēlláchthai⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἀπαλλάσσω</span>.</p>\n</section></article><article id=\"entry-aperth-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπήρθη</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apḗrthē⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἀπαίρω</span>.</p>\n</section></article><article id=\"entry-apido-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπίδω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apídō⟧</span><span class=\"separator\">·</span><span>forma verbal (remissão)</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Forma verbal; veja <span class=\"greek\">ἀφοράω</span>.</p>\n</section></article><article id=\"entry-apisteo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπιστέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apistéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Imperfeito <span class=\"greek\">ἠπίστουν</span>; primeiro aoristo <span class=\"greek\">ἠπίστησα</span>; passivo <span class=\"greek\">ἠπιστήθην</span> (Justino, <em>A I</em> 33.2; Atanásio 32.2). Veja <span class=\"greek\">ἄπιστος</span>. Homero e outros; LXX; TestSol; TestAbr A 6 p. 83, 24 [Stone p. 14]; TestLevi 4.1; Fílon; Justino; Atanásio.</p>\n<p class=\"entry-text\"><b>1.</b> <strong>Não acreditar, recusar-se a crer</strong>, intransitivo. <b>a.</b> Em sentido geral (POxy 471, 4 [século II d.C.]; Josefo, <em>Ant.</em> 2.58): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.41</a>. <span class=\"greek\">ἠπίστουν</span>, <strong>recusavam-se a crer</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.24</a>. Com dativo de pessoa, <span class=\"greek\">ἀπιστεῖν τινι</span>, <strong>não acreditar em alguém</strong> (Josefo, <em>Ant.</em> 2.330): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24.11</a>.</p>\n<p class=\"entry-text\">As inscrições SIG 1168, 24 (com verbo relativo a zombaria), 30 e 31, e Fílon, <em>Mos.</em> 1.212; 2.261, exemplificam a transição para o emprego seguinte. <b>b.</b> Da reação a uma divindade, à ação divina ou às notícias de tal ação: Jâmblico, <em>Vi. Pyth.</em> 28.148, <span class=\"greek\">περὶ θεῶν μηδὲν θαυμαστὸν ἀπιστεῖν</span>, <strong>não desacreditar de nada maravilhoso acerca dos deuses</strong>; Herm. Wr. 9.10; Wsd 1.2; 10.7; 18.13; 2Mc 8.13; Josefo, <em>Ant.</em> 2.270. <span class=\"greek\">ὁ ἀπιστήσας</span>, <strong>aquele que não dá crédito à mensagem</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 16.16</a>; <span class=\"greek\">οἱ ἀπιστοῦντες</span>, <strong>os incrédulos</strong> (Jâmblico, <em>Vi. Pyth.</em> 28.139): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 2.7</a>; IEph 18.1.</p>\n<p class=\"entry-text\"><b>2.</b> <strong>Não crer em alguém</strong>, transitivo: <span class=\"greek\">οἵτινες τὸν οὕτως ἀναστάντα ἀπιστοῦσι</span>, <strong>os que não creem naquele que assim ressuscitou</strong>, AcPlCor 2.25; compare Justino, <em>A I</em> 33.2 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 14.29</a>); Atanásio 12.3, <span class=\"greek\">ἀπιστούμεθα θεοσεβεῖν</span>. Em sociedades mediterrâneas orientadas por reciprocidade e vergonha, atitudes e reações negativas diante da beneficência divina merecem severa censura.</p>\n<p class=\"entry-text\"><b>3.</b> <strong>Ser infiel</strong>, de quem carece do sentido de obrigação (Xenofonte, <em>An.</em> 2.6.19, sobre soldados desleais); da relação dos seres humanos com Deus ou Jesus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 2.13</a>. — DELG s.v. <span class=\"greek\">πείθομαι</span>; M-M; TW.</p>\n</section></article><article id=\"entry-apistia-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπιστία</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦apistía⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἀπιστία, ας, ἡ</span>; veja <span class=\"greek\">ἀπιστέω</span>. Hesíodo, Heródoto e outros; LXX, Fílon, Josefo, Justino, Taciano 32.2; Atanásio, <em>R.</em> 60.15 e outros; veja Mayser II/1, 130.</p>\n<p class=\"entry-text\"><b>1.</b> <strong>Relutância em comprometer-se com outrem ou reagir favoravelmente às suas palavras ou ações; falta de crença, incredulidade</strong> (Mitt-Wilck. I/2, 155, 11; Josefo, <em>Ant.</em> 2.327; 19.127). Em nossa literatura, o referente é sempre Deus ou uma ação divina; compare Cercidas, <em>Iamb.</em> [século III a.C.], Fgm. 18 II, 8, Coll. Alex. p. 217 [= <em>Anon. in turpilucrum</em> 74: AnthLG, Diehl³, fasc. 3 = Knox 1929 p. 234]; Plutarco, <em>Coriol.</em> 232 [38.4], <em>Alex.</em> 706 [75.2], <span class=\"greek\">ἀπιστία πρὸς τὰ θεῖα καὶ καταφρόνησις αὐτῶν</span>, <strong>descrença nas coisas divinas e desprezo por elas</strong>; <em>De Superstit.</em> 2 p. 165b; Élio Aristides 47.66 K. = 23 p. 462 D.; Fílon, <em>Leg. ad Gai.</em> 118, <span class=\"greek\">ἀπιστία πρὸς τὸν τοῦ κόσμου παντὸς εὐεργέτην</span>, <strong>incredulidade para com o benfeitor de todo o mundo</strong> (com <span class=\"greek\">ἀχαριστία</span>), <em>Mut. Nom.</em> 201 e outros; Josefo, <em>Ant.</em> 10.142.</p>\n<p class=\"entry-text\">Reação dos habitantes de Nazaré a Jesus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.58</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.6</a>; do pai de pessoa possessa: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.24</a>; dos discípulos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.20</a>, variante textual em lugar de <span class=\"greek\">ὀλιγοπιστίαν</span>; de alguns judeus: <span class=\"greek\">[ἀ]πιστεί[α]</span> PEg² 19; dos israelitas para com Deus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.20</a>, <span class=\"greek\">τῇ ἀπιστίᾳ</span>, <strong>por causa da incredulidade deles</strong>; veja A. Charue, <em>L’Incrédulité des Juifs dans le NT</em>, 1929; sobre dativo causal Schmid III 57; IV 59; Marco Aurélio 3.1; inscrição em E. Nachmanson, <em>Eranos</em> 11 (1911) 220–225; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 11.23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.19</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">διακρίνεσθαι τῇ ἀπιστίᾳ</span>, <strong>vacilar na incredulidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 4.20</a>. <span class=\"greek\">ἐποίησα ἐν ἀπιστίᾳ</span>, <strong>agi quando ainda era incrédulo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 1.13</a>. <span class=\"greek\">καρδία πονηρὰ ἀπιστίας</span>, <strong>coração perverso de incredulidade</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3.12</a> (sobre o genitivo, Mlt. 74). Entre cristãos, junto de <span class=\"greek\">διψυχία</span>, 2Cl 19.2; com <span class=\"greek\">ἀνομία</span>, GJs 20.1 (não no papiro). Personificada entre os principais pecados, Hs 9.15.3; em oposição a <span class=\"greek\">πίστις</span>, IEph 8.2. Como característica desta era, ao lado de <span class=\"greek\">ἀνομία</span>, no final de Marcos 16.14, linha 2, do manuscrito Freer.</p>\n<p class=\"entry-text\"><b>2.</b> <strong>Ausência de compromisso numa relação ou com uma promessa; infidelidade</strong> (Xenofonte, <em>An.</em> 3.2.4 e outros; UPZ 18, 5 [163 a.C.]; Wsd 14.25; Fílon, <em>Spec. Leg.</em> 2.8; <em>Decal.</em> 172; Josefo, <em>Ant.</em> 14.349): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 3.3</a>; J. Griffiths, <em>ET</em> 53 (1941) 118. — M-M; TW.</p>\n</section></article><article id=\"entry-apistos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄπιστος</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦ápistos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἄπιστος, ον</span>; veja <span class=\"greek\">πιστός</span>. Homero e outros; LXX, Fílon, Josefo, Justino, Atanásio; Melitão, <em>P.</em> 16, 111.</p>\n<p class=\"entry-text\"><b>1.</b> <strong>Inacreditável, incrível</strong> (Baquílides 17.117; Xenofonte, <em>Cyr.</em> 3.1.26; Platão, <em>Theag.</em> 130; Herm. Wr. 9.10; EpArist 296; Fílon, <em>Op. M.</em> 114 e outros; Josefo, <em>Ant.</em> 6.198; Justino, <em>D.</em> 73.5s.; Atanásio 30.3): <span class=\"greek\">τί ἄπιστον κρίνεται παρ’ ὑμῖν;</span>, <strong>por que isso vos parece incrível?</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.26.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 26.8</a> (compare Josefo, <em>Ant.</em> 18.76, <span class=\"greek\">ἄπιστα αὐτὰ κρίνειν</span>).</p>\n<p class=\"entry-text\"><b>2.</b> <strong>Sem fé, descrente, incrédulo</strong>. Sobre ação divina já em SIG 1168, 32 [c. 320 a.C.]: paciente zomba incrédulo das curas registradas em santuário de Asclépio e depois recebe o apelido <span class=\"greek\">Ἄπιστος</span>; também <em>Hymn to Demeter</em>, PSI 1282, 42; Is 17.10; Pr 28.25 v.l.; Fílon, <em>Leg. All.</em> 3.164, <em>Leg. ad Gai.</em> 3; Justino, <em>D.</em> 91.3 e outros; Atanásio 24.4; Melitão, <em>P.</em> 16, 111.</p>\n<p class=\"entry-text\">De uma <strong>geração incrédula</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.17</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.41</a>; de Tomé, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.27</a>. Especialmente de gentios, <span class=\"greek\">οἱ ἄπιστοι</span>, <strong>os incrédulos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.6\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6.6</a>; 7.15; 10.27; 14.22; 2Cl 17.5; Dg 11.2; MPol 16.1; IMg 5.2; Papias 11.2; condenados no juízo final, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12.46</a> (compare Paroem. Gr.: Zenóbio [século II d.C.] 2.6 p. 33, 4s., <span class=\"greek\">αἱ ἀμυήτων ψυχαί</span>, <strong>as almas dos não iniciados</strong>, atormentadas no Hades).</p>\n<p class=\"entry-text\">Com <span class=\"greek\">ἰδιώτης</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14.23</a>s.; <span class=\"greek\">ἄπιστος γυνή</span>, <strong>esposa incrédula</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 7.12</a>, 14; <span class=\"greek\">ἀνήρ</span>, <strong>marido</strong>, vv. 13s. (J. Köhne, <em>Die Ehen zw. Christen u. Heiden in d. ersten christl. Jahrhunderten</em>, 1931). Com conotação de prática do mal, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6.14</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.8</a>; com <span class=\"greek\">μεμιαμμένοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Tt 1.15</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 21.8</a>. De mestres de doutrina errônea, ITr 10; ISm 2; 5.3.</p>\n<p class=\"entry-text\"><span class=\"greek\">ἐν οἷς ὁ θεὸς τοῦ αἰῶνος τούτου ἐτύφλωσεν τὰ νοήματα τῶν ἀπίστων</span>, <strong>no caso deles, o deus desta era cegou a mente dos incrédulos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 4.4</a>. — DELG s.v. <span class=\"greek\">πείθομαι</span>; M-M; TW.</p>\n</section></article><article id=\"entry-aplanes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀπλανής</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦aplanḗs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἀπλανής, ές</span>; genitivo <span class=\"greek\">οῦς</span>; adjetivo, relacionado com <span class=\"greek\">πλάνης</span> (<strong>errante</strong>). Desde Platão e Aristóteles; EpArist 2; Fílon; Josefo, <em>Ant.</em> 20.261; Taciano 9.2; Atanásio 6.3.</p>\n<p class=\"entry-text\"><strong>Que não se desvia de um curso estabelecido ou reconhecido; infalível, sem desvios, correto</strong>. <span class=\"greek\">τὴν ἀπλανῆ θεοσέβειαν</span>, <strong>o culto irrepreensível de Deus</strong>, AcPlCor 2.10. — DELG s.v. <span class=\"greek\">πλανάομαι</span>.</p>\n</section></article><article id=\"entry-haplotes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁπλότης</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦haplótēs⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἁπλότης, ητος, ἡ</span>; veja <span class=\"greek\">ἁπλοῦς</span>, <strong>simples</strong>, em oposição a <span class=\"greek\">διπλοῦς</span>, <strong>duplo</strong>. Xenofonte, Platão e outros; OGI 764, 1; Kaibel 716, 5; LXX; Test12Patr; TestJob 26.6; Fílon; Josefo; Nägeli 52. Sentido fundamental: <strong>singeleza</strong>.</p>\n<p class=\"entry-text\"><b>1.</b> Em nossa literatura, especialmente a <strong>integridade pessoal manifestada em palavras ou ações; simplicidade, sinceridade, retidão, franqueza</strong> (compare a expressão coloquial «o que você vê é o que você recebe»). <span class=\"greek\">ἐν ἁπλότητι τῆς καρδίας ὑπακούειν</span>, <strong>obedecer com coração sincero</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.5</a>; o versículo 6 mostra que isso se opõe à aparência externa que encobre motivação imprópria; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Cl 3.22</a> (Diodoro Sículo 5.66.4, <span class=\"greek\">ἁπλότης τῆς ψυχῆς</span>, <strong>sinceridade íntima</strong>; 1Cr 29.17; Wsd 1.1; TestReub 4.1; TestSim 4.5; TestLevi 13.1).</p>\n<p class=\"entry-text\">Com <span class=\"greek\">εἰλικρίνεια</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1.12</a>; compare a versão siríaca de 1Cl 60.2 (texto grego: <span class=\"greek\">ὁσιότης</span>). <span class=\"greek\">ἐν ἁπλότητι λέγειν</span>, <strong>falar simplesmente, com clareza, sem ambiguidade</strong>, B 8.2 (Dionísio de Halicarnasso, <em>Ars Rhet.</em> 9.14); <span class=\"greek\">ἐν ἁπλότητι δηλῶσαι</span>, <strong>declarar claramente</strong>, B 17.1; <span class=\"greek\">ἐν ἁπλότητι εὑρίσκεσθαι</span>, <strong>mostrar-se sincero</strong>, Hm 2.7; <span class=\"greek\">ἡ ἁπλότης ἡ εἰς Χριστόν</span>, <strong>devoção sincera a Cristo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11.3</a> (W. Wood, <em>Exp.</em>, série 9, 2 [1925] 450–453).</p>\n<p class=\"entry-text\">Da bondade simples que se dá sem reservas, <strong>sem condições ocultas ou segundas intenções; singeleza, ingenuidade</strong> (Josefo, <em>Bell.</em> 5.319, <em>Ant.</em> 7.332; TestIss 3.8), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8.2</a>; 9.11, 13. Hermas aprecia especialmente este sentido: com <span class=\"greek\">ἀκακία</span>, Hv 1.2.4; 3.9.1; com <span class=\"greek\">ἐγκράτεια</span>, Hv 2.3.2; com <span class=\"greek\">νηπιότης</span>, Hs 9.24.3; <span class=\"greek\">ἐμμένειν τῇ ἁπλότητι</span>, <strong>permanecer na sinceridade</strong>, Hv 3.1.9; <span class=\"greek\">ἁπλότητα ἔχειν</span>, Hm 2.1. Personificação junto de outras virtudes cristãs: Hv 3.8.5, 7; Hs 9.15.2.</p>\n<p class=\"entry-text\"><b>2.</b> Propôs-se frequentemente para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 12.8</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8.2</a>; 9.11, 13 o significado <strong>generosidade, liberalidade</strong>, com apoio procurado em TestIss 3.8 (R. Charles, <em>Test12Patr</em>, 1908, a TestIss 3.1, 2, 8) e Kaibel 716, 5 = IG XIV, 1517 (L-S-J-M s.v. II.3). Esse sentido, adotado pela NRSV e outras versões, <strong>é discutido</strong>; provavelmente o sentido 1, de solicitude sincera e bondade simples, basta a todas essas passagens. Aristóteles, <em>EN</em> 4.1.13s. (1120a), documenta o ideal greco-romano de dar com entusiasmo e sem relutância.</p>\n<p class=\"entry-text\">J. Amstutz, <em>ΑΠΛΟΤΗΣ</em>, 1968 (sem papiros ou inscrições). — DELG s.v. <span class=\"greek\">ἁπλόος</span>; EDNT; <em>New Docs</em> 5, 77; M-M; TW; Spicq.</p>\n</section></article><article id=\"entry-haplous-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁπλοῦς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦haploûs⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἁπλοῦς, ῆ, οῦν</span>, forma ática contraída; Ésquilo, Tucídides e outros. <strong>Caracterizado por propósito único, de maneira aberta e franca, sem astúcia nem intenção oculta; simples, sincero, direto</strong> (Plutarco, <em>Mor.</em> 63f: deuses apreciam a beneficência em si mesma, em contraste com adulação de motivos mistos).</p>\n<p class=\"entry-text\"><span class=\"greek\">εἶναι ἁπλοῦς τῇ καρδίᾳ</span>, <strong>ser sem dolo no coração</strong>, B 19.2 (SIG 1042, 12 <span class=\"greek\">ἁπλοῦς τῇ ψυχῇ</span>; Pr 11.25; Ps.-Phocyl. 50). <span class=\"greek\">ἁπλῆ διάνοια</span>, <strong>mente sincera</strong>, 1Cl 23.1. Com <span class=\"greek\">ἄκακος</span> (Diodoro Sículo 13.76; Nicolau de Damasco: 90 Fgm. 61, 2 Jac.; Apiano, <em>Bell. Civ.</em> 5.136 §566), Hs 9.24.2.</p>\n<p class=\"entry-text\">Aplicado ao <strong>olho</strong> (Damáscio, <em>Vi. Isid.</em> 16 [p. 16, 9–11 Z.], relativo à expressão franca): <strong>simples, livre de inveja, sincero</strong>, em oposição a <span class=\"greek\">πονηρός</span> (cujo significado se manifesta em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7.22</a>). Compare Sir 14.10; 31.13; TestIss 3.2, <span class=\"greek\">πορευόμενος ἐν ἁπλότητι ὀφθαλμῶν</span>; IArsameia, Antíoco I, linhas 210–220, na tentativa de ocultar inveja da boa fortuna alheia e «derreter o olho» (Danker, <em>Benefactor</em> 251). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 11.34</a> (Jülicher, <em>Gleichn.</em> 98ss., esp. 100s.; W. Brandt, <em>ZNW</em> 14 [1913] 189ss.; C. Edlund, <em>Das Auge der Einfalt</em>, ASNU 19 [1952] 51–122).</p>\n<p class=\"entry-text\">A inscrição de Comagena ajuda a explicar a inserção de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6.22</a>s. entre dois ditos sobre riqueza. H. Cadbury, «The Single Eye», <em>HTR</em> 47 (1954) 69–74, defende <strong>generoso</strong>; T. Thienemann, <em>Gordon Review</em> 1 (1955) 10–22, discorda. Plutarco, <em>Mor.</em> 63f, distingue <span class=\"greek\">ἁπλοῦς</span>, <strong>sem reservas</strong>, de <span class=\"greek\">ἐλευθέριος</span>, <strong>liberal</strong>. Veja também <span class=\"greek\">λύχνος</span> b, <span class=\"greek\">ὀφθαλμός</span> 1, <span class=\"greek\">πονηρός</span> 1b e 3a. Zahn, <em>Mt</em> p. 291, e Betz, <em>SM</em> 451, adotam um sentido fisiológico, <strong>saudável</strong>.</p>\n<p class=\"entry-text\">Também de animais em geral (Aristóteles, <em>HA</em> 9.1), no superlativo <span class=\"greek\">ἁπλούστατος</span> (Xenofonte, <em>Mem.</em> 4.2.16; Políbio 9.10.5; Estrabão 7.3.7; Fílon, <em>Vi. Cont.</em> 82), <strong>muito simples, sem malícia</strong>, das pombas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.16</a>, códice D. Comparativo <span class=\"greek\">ἁπλούστερον</span>, <strong>muito simplesmente</strong>, B 6.5 (veja <span class=\"greek\">ἁπλῶς</span>).</p>\n<p class=\"entry-text\">C. Spicq, «La vertu de Simplicité dans l’A. et le N. Test.», <em>RSPT</em> 22 (1933) 1–26; E. Sjöberg, <em>StTh</em> 5 (1951) 89–105; H. Bacht, <em>Geist u. Leben</em> 29 (1956) 416–426; J. Amstutz, <em>ΑΠΛΟΤΗΣ</em>, 1968; Betz, <em>SM</em> 437–453, esp. 449–453. — DELG s.v. <span class=\"greek\">ἁπλόος</span>; M-M; TW; Spicq; Sv.</p>\n</section></article><article id=\"entry-haploo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁπλόω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦haplóō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek\">ἁπλοῦς</span>; Herão de Alexandria III p. 130, 7; Cornuto 32 p. 66, 7; Sorano p. 76, 16; Eliano, <em>NA</em> 12.27; Ps.-Calístenes p. 36, 10; Herm. Wr., Fgm. XXIII 52 [488, 6 Sc.]; Antologia Palatina 11.107.4; Jó 22.3, <span class=\"greek\">ἁπλώσῃς τὴν ὁδόν σου</span> (variante <span class=\"greek\">ἀπώσῃς</span>, B S*); TestJob 40.8, <span class=\"greek\">νεκρὰν ἡπλωμένην</span>; GrBar 6.7, <span class=\"greek\">ἥπλωσε τὰς πτέρυγας αὐτοῦ</span>; ApcMos 37, <span class=\"greek\">ἁπλώσας τὰς χείρας</span>, das mãos estendidas num gesto receptivo.</p>\n<p class=\"entry-text\"><strong>Tornar simples, desdobrar, estender</strong>; no passivo com significado ativo (TestJob 40.8; Eliano, <em>NA</em> 14.26): <span class=\"greek\">χάρις ἁπλουμένη</span>, <strong>graça que se desdobra, isto é, generosidade continuamente estendida a outros</strong>, Dg 11.5.</p>\n</section></article><article id=\"entry-aplutos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄπλυτος</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦áplutos⟧</span><span class=\"separator\">·</span><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><span class=\"greek\">ἄπλυτος, ον</span>; de <span class=\"greek\">ἀ-</span> e <span class=\"greek\">πλυτός</span>, <strong>lavado</strong>. Semônides 7.5; Díon Crisóstomo 11[12].43; Galeno XIII 664 K.</p>\n<p class=\"entry-text\"><strong>Não lavado</strong>: <span class=\"greek\">τὸ ἔντερον ἄπλυτον φαγεῖν</span>, <strong>comer as entranhas sem lavá-las</strong>, B 7.4. — DELG s.v. <span class=\"greek\">πλύνω</span>.</p>\n</section></article><article id=\"entry-haplos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁπλῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦haplō̂s⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio derivado de <span class=\"greek\">ἁπλοῦς</span>; Ésquilo e outros.</p>\n<p class=\"entry-text\"><b>1.</b> <strong>De maneira direta, franca, sincera, aberta e sem reservas</strong>, da resposta sem dolo a algo que chama a atenção (Demóstenes 23.178; Marco Aurélio 3.6.3 e outros; Epicteto 2.2.13; Fílon, <em>Ebr.</em> 76; Justino, <em>D.</em> 65.2; Atanásio, <em>R.</em> 60.32; Irineu 5.30.1 [Harvey II 407, 6], com <span class=\"greek\">ἀκακῶς</span>). Com <span class=\"greek\">διδόναι</span>, <strong>dar sem reservas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 1.5</a> (M. Dibelius, ad loc.; H. Riesenfeld, <em>ConNeot</em> 9 [1944] 33–41); Hm 2.4, sem reconsiderar a doação (veja <span class=\"greek\">ἁπλότης</span> 1); <span class=\"greek\">ἁπλῶς τι τελέσαι</span>, <strong>realizar algo sem reservas</strong>, Hm 2.6a; compare 2b. <span class=\"greek\">προσευχὰς ἀναφέρειν</span>, <strong>oferecer orações de todo o coração, com confiança</strong>, 2Cl 2.2.</p>\n<p class=\"entry-text\">Comparativo <span class=\"greek\">ἁπλούστερον</span> (Isêo 4.2), <span class=\"greek\">γράφειν</span>, <strong>escrever de maneira muito simples</strong>, B 6.5 (compare Irineu 1, prólogo 3 [Harvey I 6, 5]).</p>\n<p class=\"entry-text\"><b>2.</b> <strong>Simplicidade de expressão verbal.</strong> <b>a.</b> <strong>Em suma, numa palavra</strong> (Epicteto 3.15.3; 3.22.96; Justino, <em>A I</em> 67.6, <span class=\"greek\">ἁπλῶς πᾶσι τοῖς ἐν χρείᾳ οὖσι</span>, <strong>em suma, a todos os necessitados</strong>; <em>D.</em> 5.4 e outros; Irineu 1.18.3 [Harvey I 172, 17]). <span class=\"greek\">ἁπλῶς εἰπεῖν</span>, <strong>exprimir sucintamente</strong>, TestAbr 10 p. 87, 27 [Stone p. 22]; 17 p. 99, 28 [Stone p. 46]; Dg 6.1. O sentido <strong>francamente, sem rodeios</strong>, não indiretamente nem de forma enganosa (Marco Aurélio 5.7.2; escólio a Apolônio de Rodes 2.844–847a, <span class=\"greek\">ἁπλῶς καὶ κατὰ ἀλήθειαν ἐξειπεῖν</span>, <strong>declarar simplesmente e conforme a verdade</strong>) é <strong>menos provável nesse contexto</strong>, porque o que precede consiste em pormenores explícitos.</p>\n<p class=\"entry-text\"><b>b.</b> <strong>Simplesmente, de modo algum</strong>, com expressões negativas (referências em Riesenfeld, obra citada, 37s.; Teopompo [século IV a.C.], 115 Fgm. 224 Jac., p. 582, 18, <span class=\"greek\">ἁπλῶς οὐδείς</span>; Diodoro Sículo 3.8.5, <span class=\"greek\">ἁπλῶς οὐ</span>; Justino, <em>A II</em> 2.16; <em>D.</em> 6.1; Eurípides, <em>Rhesus</em> 851): <span class=\"greek\">ἁπλῶς οὐ δύναμαι ἐξηγήσασθαι</span>, <strong>simplesmente não consigo descrever</strong>, ApcPt 3.9. — M-M; Spicq.</p>\n</section></article>"};
